def task_func(API_URL, endpoint, PREFIX):
    if not API_URL or not endpoint or not PREFIX:
        raise ValueError("API_URL, endpoint, and PREFIX must be non-empty strings.")

    try:
        full_url = f"{API_URL.rstrip('/')}/{endpoint.lstrip('/')}"
        response = requests.get(full_url)
        response.raise_for_status()
        data = response.json()
    except requests.RequestException as e:
        raise RuntimeError(f"Error fetching data from the API: {e}") from e

    filename = f"{PREFIX}{endpoint.replace('/', '_')}.json"

    try:
        with open(filename, 'w') as f:
            json.dump(data, f)
    except Exception as e:
        raise RuntimeError(f"Error writing data to file: {e}") from e

    return filename

